# Generated by manage.py generate_test_cases.
from django.contrib.auth import SESSION_KEY
from django.urls import reverse

from bloomerp.models.users.user import User
from bloomerp.tests.base import (
    BloomerpDetailViewTestCase,
    ExpectedResult,
    RequestScenario,
    ModelRequestScenario,
)


class TestBloomerpProfilePasswordResetView(BloomerpDetailViewTestCase):
    """Tests class `BloomerpProfilePasswordResetView` from `bloomerp/views/users/reset_password.py`."""

    view_name = 'reset_password'
    model = User

    def extendedSetup(self):
        self.normal_user.set_password("current-password-123")
        self.normal_user.save(update_fields=["password"])

    def create_test_object(self):
        return self.normal_user

    def get_test_scenarios(self) -> list[RequestScenario]:
        return [
            RequestScenario(
                name="User can open their own password reset form",
                description=(
                    "UC: A signed-in user opens their own password reset page.\n"
                    "Expected Result: The old-password field is rendered."
                ),
                user=self.normal_user,
                expected=ExpectedResult(response_validators=self.contains_text('name="old_password"')),
            ),
            RequestScenario(
                name="User resets own password without losing session",
                description=(
                    "UC: A user supplies their current password and matching new passwords.\n"
                    "Expected Result: The password changes, the session remains authenticated, and profile redirect is returned."
                ),
                method="POST",
                user=self.normal_user,
                data={
                    "old_password": "current-password-123",
                    "new_password1": "new-password-456",
                    "new_password2": "new-password-456",
                },
                expected=ExpectedResult(
                    status_code=302,
                    response_validators=self.own_password_was_reset,
                ),
            ),
            RequestScenario(
                name="Non-superuser cannot reset another user's password",
                description=(
                    "UC: A user opens another user's self-service reset route.\n"
                    "Expected Result: The view returns 403."
                ),
                user=self.normal_user,
                prepare=[self.refresh_normal_user, self.target_other_user],
                expected=ExpectedResult(status_code=403),
            ),
        ]

    def refresh_normal_user(self, _scenario):
        self.normal_user.refresh_from_db()

    def target_other_user(self, scenario):
        other = User.objects.create_user(
            username="other-user",
            password="other-password-123",
        )
        scenario.view_kwargs = {"pk": other.pk}

    def own_password_was_reset(self, response):
        self.normal_user.refresh_from_db()
        return (
            self.normal_user.check_password("new-password-456")
            and self.client.session.get(SESSION_KEY) == str(self.normal_user.pk)
            and response.headers.get("Location") == reverse("users_my_profile_overview")
        )
